import { Router, Request, Response, NextFunction } from "express";
export default class ExpressServer {
    #private;
    constructor();
    views(engine?: string, path?: string): void;
    addMiddleware(callback: (req: Request, res: Response, next: NextFunction) => void): void;
    addRoute(endpoint: string, router: Router): void;
    errorHandler(errorHandlerFunction: (err: any, req: Request, res: Response, next: NextFunction) => void): void;
    fallbackRouter(fallbackFunction: (req: Request, res: Response) => void): void;
    healthCheckRouter(endpoint?: string, healthCheckFunction?: (req: Request, res: Response) => void): void;
    start(port: number): void;
}
